    }

    @Override
    public void setWorking(final boolean isWorking)
    {
        if (isWorking && !this.isWorking)
        {
            if (job != null)
            {
                this.isWorking = isWorking;
                job.triggerActivityChangeAction(isWorking);
            }
            inactivityTimer = DISABLED;
        }
        else if (!isWorking && this.isWorking)
        {
            inactivityTimer = 0;
            this.isWorking = isWorking;
        }
