import com.minecolonies.api.research.*;
import com.minecolonies.api.research.IResearchEffect;
import com.minecolonies.api.research.IResearchEffectManager;
import com.minecolonies.api.research.util.ResearchState;
import com.minecolonies.api.util.MessageUtils;
import com.minecolonies.api.util.SoundUtils;
import com.minecolonies.core.Network;
import com.minecolonies.core.colony.Colony;
import com.minecolonies.core.network.messages.client.colony.ColonyViewResearchManagerViewMessage;
import com.minecolonies.core.research.LocalResearch;
import com.minecolonies.core.research.LocalResearchTree;
import com.minecolonies.core.research.ResearchEffectManager;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.block.Block;
import net.minecraftforge.registries.ForgeRegistries;
import org.jetbrains.annotations.NotNull;

import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

import static com.minecolonies.api.util.constant.TranslationConstants.*;

/**
 * Research manager of the colony.
 */
public class ResearchManager implements IResearchManager
{
    /**
     * The research tree of the colony, containing completed or in-progress research.
     */
    private final LocalResearchTree tree;

    /**
     * The active research effects of the colony.
     */
    private final IResearchEffectManager effects = new ResearchEffectManager();

    /**
     * The research Ids of any research set to start automatically when unhidden.
     */
    private final List<IGlobalResearch> autoStartResearch = new ArrayList<>();

    /**
     * The colony the ResearchManager applies toward.
     * This may be a ColonyView, where the ResearchManager is inside of a ColonyView.
     */
    private final IColony colony;

    /**
     * Whether synch to client is necessary.
     */
    private boolean dirty;

    @Override
    public void readFromNBT(@NotNull final CompoundTag compound)
    {
        tree.readFromNBT(compound, effects);
    }

    @Override
    public void writeToNBT(@NotNull final CompoundTag compound)
    {
        tree.writeToNBT(compound);
    }

    @Override
    public void sendPackets(final Set<ServerPlayer> closeSubscribers, final Set<ServerPlayer> newSubscribers)
    {
        if (dirty || !newSubscribers.isEmpty())
        {
            final Set<ServerPlayer> players = new HashSet<>();
            if (dirty)
            {
                players.addAll(closeSubscribers);
            }
            players.addAll(newSubscribers);

            final ColonyViewResearchManagerViewMessage message = new ColonyViewResearchManagerViewMessage(colony, this);
            players.forEach(player -> Network.getNetwork().sendToPlayer(message, player));

        }
        clearDirty();
    }

    @Override
    public final void markDirty()
    {
        dirty = true;
    }

    @Override
    public final boolean isDirty()
    {
        return dirty;
    }

    @Override
    public void clearDirty()
    {
        dirty = false;
    }

    public ResearchManager(IColony colony)
    {
        this.colony = colony;
        autoStartResearch.addAll(MinecoloniesAPIProxy.getInstance().getGlobalResearchTree().getAutostartResearches());
        this.tree = new LocalResearchTree(colony);
    }

    @Override
    public LocalResearchTree getResearchTree()
    {
        return this.tree;
    }

    @Override
    public IResearchEffectManager getResearchEffects()
    {
        return this.effects;
    }

    @Override
    public ResourceLocation getResearchEffectIdFrom(Block block)
    {
        return new ResourceLocation(ForgeRegistries.BLOCKS.getKey(block).getNamespace(), "effects/" + ForgeRegistries.BLOCKS.getKey(block).getPath());
    }

    @Override
    public void checkAutoStartResearch()
    {
        if(colony == null || !(colony instanceof Colony))
        {
            return;
        }
        final List<IGlobalResearch> removes = new ArrayList<>();
        for(IGlobalResearch research : autoStartResearch)
        {
            if (!IGlobalResearchTree.getInstance().isResearchRequirementsFulfilled(research.getResearchRequirements(), colony))
            {
                continue;
            }
            // Unlockable Branch Research should trigger even if the university isn't at the required depth. Otherwise, we do need to consider it. CheckAutoStart will rerun on the university upgrade completion.
            if(IGlobalResearchTree.getInstance().getBranchData(research.getBranch()).getType() != ResearchBranchType.UNLOCKABLES)
            {
                int level = 0;
                Map<BlockPos, IBuilding> buildings = colony.getServerBuildingManager().getBuildings();
                for (Map.Entry<BlockPos, IBuilding> building : buildings.entrySet())
                {
                    if (building.getValue().getBuildingType() == ModBuildings.university.get())
                    {
                        if (building.getValue().getBuildingLevel() > level)
                        {
                            level = building.getValue().getBuildingLevel();
                        }
                    }
                }
                if (level < research.getDepth())
                {
                    continue;
                }
            }

            boolean researchAlreadyRun = false;
            for (ILocalResearch progressResearch : colony.getResearchManager().getResearchTree().getResearchInProgress())
            {
                if(progressResearch.getId().equals(research.getId()))
                {
                    researchAlreadyRun = true;
                    break;
                }
            }
            // Don't want to spam people about in-progress or already-completed research.  Because these might change within a world,
            // we can't just save them or check against effects.
            if(researchAlreadyRun || colony.getResearchManager().getResearchTree().hasCompletedResearch(research.getId()))
            {
                removes.add(research);
                continue;
            }

            // if research has item requirements, only notify player; we don't want to have items disappearing from inventories.
            if (!research.getCostList().isEmpty())
            {
                MessageUtils.format(RESEARCH_AVAILABLE, MutableComponent.create(research.getName())).sendTo(colony).forAllPlayers();
                for (Player player : colony.getMessagePlayerEntities())
                {
                    SoundUtils.playSuccessSound(player, player.blockPosition());
                }
            }
            // Otherwise, we can start the research without user intervention.
            else
            {
                startCostlessResearch(research);
            }
            //  If we've successfully done all those things, now we can remove the object from the list.
            //  This will re-announce on world reload, but that's probably ideal, in case someone missed the message once.
            removes.add(research);
        }
        autoStartResearch.removeAll(removes);
        markDirty();
    }

    /**
     * Start researches that have no item consumption cost, and notify players of available for those with a cost.
     * @param research      The global research to start.
     */
    private void startCostlessResearch(IGlobalResearch research)
    {
        markDirty();
        boolean creativePlayer = false;
        for (Player player : colony.getMessagePlayerEntities())
        {
            if (player.isCreative())
            {
                creativePlayer = true;
            }
        }
        tree.addResearch(research.getBranch(), new LocalResearch(research.getId(), research.getBranch(), research.getDepth()));
        if(research.isInstant() || (creativePlayer && MinecoloniesAPIProxy.getInstance().getConfig().getServer().researchCreativeCompletion.get()))
        {
            ILocalResearch localResearch = tree.getResearch(research.getBranch(), research.getId());
            localResearch.setProgress(IGlobalResearchTree.getInstance().getBranchData(research.getBranch()).getBaseTime(research.getDepth()));
            localResearch.setState(ResearchState.FINISHED);
            tree.finishResearch(research.getId());
            for (IResearchEffect effect : IGlobalResearchTree.getInstance().getResearch(research.getBranch(), research.getId()).getEffects())
            {
                effects.applyEffect(effect);
            }
            for (final ICitizenData citizen : colony.getCitizenManager().getCitizens())
            {
                citizen.applyResearchEffects();
            }

            MessageUtils.format(RESEARCH_CONCLUDED + ThreadLocalRandom.current().nextInt(3),
                MutableComponent.create(IGlobalResearchTree.getInstance().getResearch(research.getBranch(), research.getId()).getName()))
              .sendTo(colony)
              .forAllPlayers();
            for (Player player : colony.getMessagePlayerEntities())
            {
                SoundUtils.playSuccessSound(player, player.blockPosition());
            }
        }
        else
        {
            MessageUtils.format(RESEARCH_AVAILABLE, MutableComponent.create(research.getName()))
              .append(MESSAGE_RESEARCH_STARTED, MutableComponent.create(research.getName()))
              .sendTo(colony)
              .forAllPlayers();
            for (Player player : colony.getMessagePlayerEntities())
            {
                SoundUtils.playSuccessSound(player, player.blockPosition());
            }
        }
    }
}

package com.minecolonies.core.entity.ai.workers.education;

import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.entity.ai.statemachine.AITarget;
import com.minecolonies.api.entity.ai.statemachine.states.IAIState;
import com.minecolonies.api.research.ILocalResearch;
import com.minecolonies.core.colony.buildings.workerbuildings.BuildingUniversity;
import com.minecolonies.core.colony.jobs.JobResearch;
import com.minecolonies.core.entity.ai.workers.AbstractEntityAIInteract;
import net.minecraft.core.BlockPos;
import net.minecraft.sounds.SoundEvents;
import org.jetbrains.annotations.NotNull;

import java.util.List;

import static com.minecolonies.api.entity.ai.statemachine.states.AIWorkerState.*;
import static com.minecolonies.api.util.constant.Constants.TICKS_SECOND;

public class EntityAIWorkResearcher extends AbstractEntityAIInteract<JobResearch, BuildingUniversity>
{
    /**
     * Delay for each subject study.
     */
    public static final int STUDY_DELAY = 1200;

    /**
     * base XP gained per study position
     */
    private static final double XP_PER_STUDYPOS = 2;

    /**
     * The current pos to study at.
     */
    private BlockPos studyPos = null;

    /**
     * How long they tried walking to a given study pos.
     */
    public int walkDelay = 0;

    /**
     * Constructor for the AI
     *
     * @param job the job to fulfill
     */
    public EntityAIWorkResearcher(@NotNull final JobResearch job)
    {
        super(job);
        super.registerTargets(
          new AITarget(IDLE, START_WORKING, 1),
          new AITarget(START_WORKING, this::startWorkingAtOwnBuilding, TICKS_SECOND),
          new AITarget(STUDY, this::study, TICKS_SECOND)
        );
        worker.setCanPickUpLoot(true);
    }

    @Override
    public Class<BuildingUniversity> getExpectedBuildingClass()
    {
        return BuildingUniversity.class;
    }

    /**
     * The AI task for the student to study. For this he should walk between the different bookcase hit them once and then stand around for a while.
     *
     * @return the next IAIState.
     */
    private IAIState study()
    {
        if (studyPos == null)
        {
            studyPos = building.getRandomBookShelf();
        }

        if (!walkToWorkPos(studyPos) && walkDelay < STUDY_DELAY)
        {
            walkDelay += TICKS_SECOND;
            return getState();
        }
        walkDelay = 0;

        final IColony colony = building.getColony();
        final List<ILocalResearch> inProgress = colony.getResearchManager().getResearchTree().getResearchInProgress();
        if (!inProgress.isEmpty() && job.getCurrentMana() > 0)
        {
            final ILocalResearch research = inProgress.get(worker.getRandom().nextInt(inProgress.size()));

            if (colony.getResearchManager()
                  .getResearchTree()
                  .getResearch(research.getBranch(), research.getId())
                  .research(colony.getResearchManager().getResearchEffects(), colony.getResearchManager().getResearchTree()))
            {
                building.onSuccess(research);
            }
            colony.getResearchManager().markDirty();
            job.reduceCurrentMana();
        }

        worker.decreaseSaturationForContinuousAction();
        worker.getCitizenExperienceHandler().addExperience(XP_PER_STUDYPOS);
        studyPos = null;
        worker.queueSound(SoundEvents.BOOK_PAGE_TURN, worker.blockPosition().above(), 80, 15, 0.25f, 1.5f);
        setDelay(STUDY_DELAY);
        return START_WORKING;
    }

    /**
     * Redirects the student to his library.
     *
     * @return the next state.
     */
    private IAIState startWorkingAtOwnBuilding()
    {
        if (!walkToBuilding())
        {
            return getState();
        }

        if (studyPos == null)
        {
            studyPos = building.getRandomBookShelf();
        }

        return STUDY;
    }
}

package com.minecolonies.core.entity.citizen.citizenhandlers;

import com.minecolonies.api.colony.ICitizenData;
import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.colony.buildings.IBuilding;
import com.minecolonies.api.entity.citizen.AbstractEntityCitizen;
import com.minecolonies.api.entity.citizen.Skill;
import com.minecolonies.api.entity.citizen.citizenhandlers.ICitizenSkillHandler;
import com.minecolonies.core.Network;
import com.minecolonies.core.network.messages.client.VanillaParticleMessage;
import com.minecolonies.core.util.ExperienceUtils;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Random;

import static com.minecolonies.api.sounds.EventType.SUCCESS;
import static com.minecolonies.api.util.SoundUtils.playSoundAtCitizenWith;
import static com.minecolonies.api.util.constant.CitizenConstants.MAX_CITIZEN_LEVEL;
import static com.minecolonies.api.util.constant.Constants.MAX_BUILDING_LEVEL;
import static com.minecolonies.api.util.constant.NbtTagConstants.*;

/**
 * The citizen skill handler of the citizen.
 */
public class CitizenSkillHandler implements ICitizenSkillHandler
{
    /**
     * Skill map.
     */
    public Map<Skill, SkillData> skillMap = new EnumMap<>(Skill.class);

    public CitizenSkillHandler()
    {
        for (final Skill skill : Skill.values())
        {
            skillMap.put(skill, new SkillData(1, 0.0D));
        }
    }

    @Override
    public void init(final int levelCap)
    {
        if (levelCap <= 1)
        {
            for (final Skill skill : Skill.values())
            {
                skillMap.put(skill, new SkillData(1, 0.0D));
            }
        }
        else
        {
            final Random random = new Random();
            for (final Skill skill : Skill.values())
            {
                skillMap.put(skill, new SkillData(random.nextInt(levelCap - 1) + 1, 0.0D));
            }
        }
    }

    @Override
    public void init(@NotNull final IColony colony, @Nullable final ICitizenData firstParent, @Nullable final ICitizenData secondParent, final Random rand)
    {
        ICitizenData roleModelA;
        ICitizenData roleModelB;

        if (firstParent == null)
        {
            roleModelA = colony.getCitizenManager().getRandomCitizen();
        }
        else
        {
            roleModelA = firstParent;
        }

        if (secondParent == null)
        {
            roleModelB = colony.getCitizenManager().getRandomCitizen();
        }
        else
        {
            roleModelB = secondParent;
        }

        final int levelCap = (int) colony.getOverallHappiness();
        init(levelCap);

        final int bonusPoints = 25 + rand.nextInt(25);

        int totalPoints = 0;
        for (final Skill skill : Skill.values())
        {
            final int firstRoleModelLevel = roleModelA.getCitizenSkillHandler().getSkills().get(skill).level;
            final int secondRoleModelLevel = roleModelB.getCitizenSkillHandler().getSkills().get(skill).level;
            totalPoints += firstRoleModelLevel + secondRoleModelLevel;
        }

        for (final Skill skill : Skill.values())
        {
            final double firstRoleModelLevel = roleModelA.getCitizenSkillHandler().getSkills().get(skill).level;
            final double secondRoleModelLevel = roleModelB.getCitizenSkillHandler().getSkills().get(skill).level;

            int newPoints = (int) (((firstRoleModelLevel + secondRoleModelLevel) / totalPoints) * bonusPoints);
            skillMap.get(skill).level += newPoints;
        }
    }

    @NotNull
    @Override
    public CompoundTag write()
    {
        final CompoundTag compoundNBT = new CompoundTag();

        @NotNull final ListTag levelTagList = new ListTag();
        for (@NotNull final Map.Entry<Skill, SkillData> entry : skillMap.entrySet())
        {
            if (entry.getKey() != null && entry.getValue() != null)
            {
                @NotNull final CompoundTag levelCompound = new CompoundTag();
                levelCompound.putInt(TAG_SKILL, entry.getKey().ordinal());
                levelCompound.putInt(TAG_LEVEL, entry.getValue().level);
                levelCompound.putDouble(TAG_EXPERIENCE, entry.getValue().experience);
                levelTagList.add(levelCompound);
            }
        }
        compoundNBT.put(TAG_LEVEL_MAP, levelTagList);

        return compoundNBT;
    }

    @Override
    public void read(@NotNull final CompoundTag compoundNBT)
    {
        final ListTag levelTagList = compoundNBT.getList(TAG_LEVEL_MAP, Tag.TAG_COMPOUND);
        for (int i = 0; i < levelTagList.size(); ++i)
        {
            final CompoundTag levelExperienceAtJob = levelTagList.getCompound(i);
            skillMap.put(Skill.values()[levelExperienceAtJob.getInt(TAG_SKILL)],
              new SkillData(Math.max(1, Math.min(levelExperienceAtJob.getInt(TAG_LEVEL), MAX_CITIZEN_LEVEL)), levelExperienceAtJob.getDouble(TAG_EXPERIENCE)));
        }
    }

    @Override
    public boolean tryLevelUpIntelligence(@NotNull final Random random, final double customChance, @NotNull final ICitizenData citizen)
    {
        if (customChance > 0 && random.nextDouble() * customChance < 1)
        {
            return false;
        }

        final int levelCap = (int) citizen.getCitizenHappinessHandler().getHappiness(citizen.getColony(), citizen);
        if (skillMap.get(Skill.Intelligence).level < levelCap * 9)
        {
            addXpToSkill(Skill.Intelligence, 10, citizen);
        }
        return true;
    }

    @Override
    public int getLevel(@NotNull final Skill skill)
    {
        return skillMap.get(skill).level;
    }

    @Override
    public void incrementLevel(@NotNull final Skill skill, final int level)
    {
        final SkillData current = skillMap.get(skill);
        current.level = Math.min(MAX_CITIZEN_LEVEL, Math.max(current.level + level, 1));
    }

    @Override
    public void addXpToSkill(final Skill skill, final double xp, final ICitizenData data)
    {
        final SkillData skillData = skillMap.getOrDefault(skill, new SkillData(0, 0.0D));

        final IBuilding home = data.getHomeBuilding();

        final double citizenHutLevel = home == null ? 0 : home.getBuildingLevelEquivalent();
        final double citizenHutMaxLevel = home == null ? MAX_BUILDING_LEVEL : home.getMaxBuildingLevel();

        if (((citizenHutLevel < citizenHutMaxLevel || citizenHutMaxLevel < MAX_BUILDING_LEVEL) && (citizenHutLevel + 1) * 10 <= skillData.level)
              || skillData.level >= MAX_CITIZEN_LEVEL)
        {
            return;
        }

        final int orgLevel = skillData.level;
        double xpToLevelUp = Math.min(Double.MAX_VALUE, skillData.experience + xp);
        while (xpToLevelUp > 0)
        {
            final double nextLevel = ExperienceUtils.getXPNeededForNextLevel(skillData.level);
            if (nextLevel > xpToLevelUp)
            {
                skillData.experience = xpToLevelUp;
                break;
            }
            else
            {
                xpToLevelUp = xpToLevelUp - nextLevel;
                skillData.level++;
            }
        }

        if (skillData.level > orgLevel)
        {
            levelUp(data);
            data.markDirty(10);
        }
    }

    @Override
    public void removeXpFromSkill(@NotNull final Skill skill, final double xp, @NotNull final ICitizenData data)
    {
        final SkillData skillData = skillMap.get(skill);

        double xpToRemove = xp;
        while (xpToRemove > 0)
        {
            if (skillData.experience >= xpToRemove || skillData.level <= 1)
            {
                skillData.experience = Math.max(0, skillData.experience - xpToRemove);
                break;
            }
            else
            {
                xpToRemove -= skillData.experience;
                skillData.experience = ExperienceUtils.getXPNeededForNextLevel(skillData.level - 1);
                skillData.level--;
                data.markDirty(40);
            }
        }
    }

    @Override
    public void levelUp(final ICitizenData data)
    {
        // Show level-up particles
        if (data.getEntity().isPresent())
        {
            final AbstractEntityCitizen citizen = data.getEntity().get();
            playSoundAtCitizenWith(citizen.level, citizen.blockPosition(), SUCCESS, data);
            Network.getNetwork()
              .sendToTrackingEntity(new VanillaParticleMessage(citizen.getX(), citizen.getY(), citizen.getZ(), ParticleTypes.HAPPY_VILLAGER),
                data.getEntity().get());
        }

        if (data.getJob() != null)
        {
            data.getJob().onLevelUp();
        }
    }

    @Override
    public double getTotalXP()
    {
        double totalXp = 0;
        for (SkillData tuple : skillMap.values())
        {
            totalXp += tuple.experience;
        }
        return totalXp;
    }

    @Override
    public Map<Skill, SkillData> getSkills()
    {
        return Collections.unmodifiableMap(skillMap);
    }

    public static class SkillData
    {
        private int    level;
        private double experience;

        private SkillData(final int level, final double experience)
        {
            this.level = level;
            this.experience = experience;
        }

        public int getLevel()
        {
            return level;
        }

        public void setLevel(final int level)
        {
            this.level = level;
        }

        public double getExperience()
        {
            return experience;
        }

        public void setExperience(final double experience)
        {
            this.experience = experience;
        }
    }
}

package com.minecolonies.core.quests;

import com.minecolonies.api.colony.ICitizenData;
import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.quests.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.IntTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Player;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

import static com.minecolonies.api.util.constant.NbtTagConstants.*;

/**
 * Instance of a specific quest type
 */
public class QuestInstance implements IQuestInstance
{
    /**
     * Colony reference
     */
    private final IColony colony;

    /**
     * The id of this quest
     */
    private ResourceLocation questTemplateID;

    /**
     * Quest giver.
     */
    private int questGiver = Integer.MIN_VALUE;

    /**
     * Quest participants.
     */
    private final List<Integer> questParticipants = new ArrayList<>();

    /**
     * The day the quest was assigned to the colony.
     */
    private int assignmentStart;

    /**
     * Current objective progress.
     */
    private int objectiveProgress = 0;

    /**
     * Tracking data of the currently active objective.
     */
    private IObjectiveInstance currentObjectiveInstance = null;

    /**
     * The player that accepted this.
     */
    private UUID assignedPlayer = null;

    /**
     * Create a new colony quest.
     * @param questTemplateID the global id of the quest.
     * @param colony the colony it belongs to.
     * @param triggerReturnData the trigger return data that made this quest available.
     */
    public QuestInstance(final ResourceLocation questTemplateID, final IColony colony, final List<ITriggerReturnData<?>> triggerReturnData)
    {
        this.colony = colony;
        this.questTemplateID = questTemplateID;
        this.assignmentStart = colony.getDay();
        questParticipants.clear();

        for (final ITriggerReturnData<?> data : triggerReturnData)
        {
            if (data.getContent() instanceof IQuestGiver && questGiver == Integer.MIN_VALUE)
            {
                questGiver = ((ICitizenData) data.getContent()).getId();
                ((ICitizenData) data.getContent()).assignQuest(this);
            }
            else if (data.getContent() instanceof IQuestParticipant)
            {
                questParticipants.add(((ICitizenData) data.getContent()).getId());
                ((ICitizenData) data.getContent()).addQuestParticipation(this);
            }
        }
        IQuestManager.GLOBAL_SERVER_QUESTS.get(questTemplateID).getObjective(this.objectiveProgress).startObjective(this);
    }

    /**
     * Create an empty colony quest obj to deserialize the data from.
     * @param colony the colony it is assigned to.
     */
    public QuestInstance(final IColony colony)
    {
        this.colony = colony;
    }

    public IColony getColony()
    {
        return colony;
    }

    @Override
    public UUID getAssignedPlayer()
    {
        return assignedPlayer;
    }

    @Override
    public void onStart(final Player player, final IColony colony)
    {
        // Reset quest timeout on acceptance.
        assignmentStart = colony.getDay();
        assignedPlayer = player.getUUID();
        colony.getQuestManager().attemptAcceptQuest(this.getId(), player);
        // activeEffects.addAll(type.createEffectsFor(this));
    }

    @Override
    public IQuestGiver getQuestGiver()
    {
        return colony.getCitizenManager().getCivilian(questGiver);
    }

    @Override
    public int getQuestGiverId()
    {
        return questGiver;
    }

    @Override
    public boolean isValid(final IColony colony)
    {
        if (questGiver == Integer.MIN_VALUE || colony.getCitizenManager().getCivilian(questGiver) == null )
        {
            return false;
        }

        for (final int participant : questParticipants)
        {
            if (colony.getCitizenManager().getCivilian(participant) == null)
            {
                return false;
            }
        }
        return colony.getDay() - assignmentStart < IQuestManager.GLOBAL_SERVER_QUESTS.get(questTemplateID).getQuestTimeout();
    }

    @Override
    public ResourceLocation getId()
    {
        return questTemplateID;
    }

    @Override
    public void onDeletion()
    {
        if (questGiver != Integer.MIN_VALUE && colony.getCitizenManager().getCivilian(questGiver) != null)
        {
            colony.getCitizenManager().getCivilian(questGiver).onQuestDeletion(this.getId());
        }

        for (final int participant : questParticipants)
        {
            if (colony.getCitizenManager().getCivilian(participant) != null)
            {
                colony.getCitizenManager().getCivilian(participant).onQuestDeletion(this.getId());
            }
        }

        final IQuestTemplate instance = IQuestManager.GLOBAL_SERVER_QUESTS.get(questTemplateID);
        if (instance != null && instance.getObjective(this.objectiveProgress) != null)
        {
            instance.getObjective(this.objectiveProgress).onCancellation(this);
        }
        colony.getQuestManager().deleteQuest(this.questTemplateID);
    }

    @Override
    public void advanceObjective(final Player player)
    {
        this.advanceObjective(player, this.objectiveProgress + 1);
    }

    @Override
    public void onWorldLoad()
    {
        IQuestManager.GLOBAL_SERVER_QUESTS.get(questTemplateID).getObjective(this.objectiveProgress).onWorldLoad(this);
    }

    @Override
    public IObjectiveInstance advanceObjective(final Player player, final int nextObjective)
    {
        final IQuestTemplate questData = IQuestManager.GLOBAL_SERVER_QUESTS.get(questTemplateID);
        final IQuestObjectiveTemplate questObjectiveTemplate = questData.getObjective(this.objectiveProgress);

        // Always when advancing an objective, get the rewards from the current objective.
        final List<Integer> rewards = questObjectiveTemplate.getRewardUnlocks();
        if(!rewards.isEmpty())
        {
            questData.unlockQuestRewards(colony, player, this, rewards);
        }

        colony.markDirty();
        if (nextObjective == -1)
        {
            this.onCompletion();
            return null;
        }

        if (this.objectiveProgress == 0)
        {
            this.onStart(player, getColony());
        }
        this.objectiveProgress = nextObjective;
        if (this.objectiveProgress >= questData.getObjectiveCount())
        {
            this.onCompletion();
            return null;
        }
        currentObjectiveInstance = questData.getObjective(this.objectiveProgress).startObjective(this);
        return currentObjectiveInstance;
    }

    @Override
    public void onCompletion()
    {
        colony.getQuestManager().completeQuest(this.getId());
        final ICitizenData questGiverData = colony.getCitizenManager().getCivilian(questGiver);
        if (questGiverData != null)
        {
            questGiverData.onQuestCompletion(this.questTemplateID);
        }

        for (final int partId : questParticipants)
        {
            final ICitizenData partData = colony.getCitizenManager().getCivilian(partId);
            if (partData != null)
            {
                partData.onQuestCompletion(this.questTemplateID);
            }
        }

        if (assignedPlayer != null)
        {
            final Player player = colony.getWorld().getPlayerByUUID(assignedPlayer);
            if (player != null)
            {
                final IQuestTemplate questData = IQuestManager.GLOBAL_SERVER_QUESTS.get(questTemplateID);
                player.sendSystemMessage(Component.translatable("com.minecolonies.coremod.quest.completed", questData.getName()));
            }
        }
    }

    @Override
    public CompoundTag serializeNBT()
    {
        final CompoundTag compoundNBT = new CompoundTag();
        compoundNBT.putString(TAG_ID, questTemplateID.toString());
        compoundNBT.putInt(TAG_ASSIGN_START, assignmentStart);
        compoundNBT.putInt(TAG_PROGRESS, objectiveProgress);
        compoundNBT.putInt(TAG_QUEST_GIVER, questGiver);
        final ListTag participantList = new ListTag();
        for (final int citizenData : this.questParticipants)
        {
            participantList.add(IntTag.valueOf(citizenData));
        }
        compoundNBT.put(TAG_PARTICIPANTS, participantList);

        if (currentObjectiveInstance != null)
        {
            compoundNBT.put(TAG_OBJECTIVE, this.currentObjectiveInstance.serializeNBT());
        }

        if (assignedPlayer != null)
        {
            compoundNBT.putUUID(TAG_PLAYER, assignedPlayer);
        }

        return compoundNBT;
    }

    @Override
    public void deserializeNBT(final CompoundTag nbt)
    {
        questTemplateID = new ResourceLocation(nbt.getString(TAG_ID));
        assignmentStart = nbt.getInt(TAG_ASSIGN_START);
        objectiveProgress = nbt.getInt(TAG_PROGRESS);
        questGiver = nbt.getInt(TAG_QUEST_GIVER);

        final ListTag participantList = nbt.getList(TAG_PARTICIPANTS, Tag.TAG_INT);
        for (final Tag tag : participantList)
        {
            questParticipants.add(((IntTag) tag).getAsInt());
        }

        if (nbt.contains(TAG_OBJECTIVE))
        {
            final IObjectiveInstance data = IQuestManager.GLOBAL_SERVER_QUESTS.get(questTemplateID).getObjective(objectiveProgress).createObjectiveInstance();
            data.deserializeNBT(nbt.getCompound(TAG_OBJECTIVE));
            this.currentObjectiveInstance = data;
        }

        if (nbt.contains(TAG_PLAYER))
        {
            assignedPlayer = nbt.getUUID(TAG_PLAYER);
        }
    }

    @Override
    public int getObjectiveIndex()
    {
        return objectiveProgress;
    }

    @Override
    public IQuestParticipant getParticipant(final int target)
    {
        return colony.getCitizenManager().getCivilian(questParticipants.get(target-1));
    }

    @Override
    public List<Integer> getParticipants()
    {
        return questParticipants;
    }

    @Override
    public int getQuestTarget()
    {
        final IQuestObjectiveTemplate objective = QuestManager.GLOBAL_SERVER_QUESTS.get(questTemplateID).getObjective(getObjectiveIndex());
        if (objective == null)
        {
            return getQuestGiverId();
        }
        final int target = objective.getTarget();
        if (target == 0)
        {
            return getQuestGiverId();
        }
        if (target <= questParticipants.size())
        {
            return questParticipants.get(target - 1);
        }
        return getQuestGiverId();
    }

    @Override
    @Nullable
    public IObjectiveInstance getCurrentObjectiveInstance()
    {
        return currentObjectiveInstance;
    }
}

package com.minecolonies.core.quests;

import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.quests.FinishedQuest;
import com.minecolonies.api.quests.IQuestInstance;
import com.minecolonies.api.quests.IQuestManager;
import com.minecolonies.api.quests.IQuestTemplate;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Player;

import java.util.*;

import static com.minecolonies.api.util.constant.NbtTagConstants.*;

/**
 * Quest manager of each colony.
 */
public class QuestManager implements IQuestManager
{
    /**
     * All quests that have been unlocked.
     */
    private final Map<ResourceLocation, IQuestInstance> availableQuests = new HashMap<>();

    /**
     * All quests that have been finished. And how often.
     */
    private final Map<ResourceLocation, Integer> finishedQuests = new HashMap<>();

    /**
     * All quests in progress.
     */
    private final Map<ResourceLocation, IQuestInstance> inProgressQuests = new HashMap<>();

    /**
     * Unlocked quest requirements.
     */
    private final List<ResourceLocation> unlockedQuests = new ArrayList<>();

    /**
     * Cached mapped results for the finished quests.
     */
    private List<FinishedQuest> finishedQuestsCache = null;

    /**
     * Quest reputation.
     */
    private double questReputation = 0;

    /**
     * This manager's colony
     */
    private final IColony colony;

    /**
     * Tracks if data needs to be sent
     */
    private boolean isDirty = true;

    public QuestManager(final IColony colony)
    {
        this.colony = colony;
    }

    @Override
    public boolean attemptAcceptQuest(final ResourceLocation questID, final Player player)
    {
        final IQuestInstance quest = availableQuests.getOrDefault(questID, null);
        if (quest == null || !quest.isValid(colony))
        {
            return false;
        }
        this.inProgressQuests.put(questID, quest);
        this.availableQuests.remove(questID);
        markDirty();
        return true;
    }

    @Override
    public void alterReputation(final double difference)
    {
        this.questReputation += difference;
        markDirty();
    }

    @Override
    public double getReputation()
    {
        return this.questReputation;
    }

    @Override
    public void completeQuest(final ResourceLocation questId)
    {
        if (inProgressQuests.containsKey(questId))
        {
            inProgressQuests.remove(questId);
            finishedQuests.put(questId, finishedQuests.getOrDefault(questId, 0) + 1);
            markDirty();
        }
        else if (availableQuests.containsKey(questId))
        {
            // When a player short-cut quits a job without accepting it. (E.g. been there, done that options).
            availableQuests.remove(questId);
            finishedQuests.put(questId, finishedQuests.getOrDefault(questId, 0) + 1);
            markDirty();
        }

        finishedQuestsCache = null;
    }

    @Override
    public void onColonyTick()
    {
        for (final Map.Entry<ResourceLocation, IQuestTemplate> quest : GLOBAL_SERVER_QUESTS.entrySet())
        {
            if (availableQuests.containsKey(quest.getKey())
                  || inProgressQuests.containsKey(quest.getKey())
                  || finishedQuests.getOrDefault(quest.getKey(), 0) >= quest.getValue().getMaxOccurrence())
            {
                continue;
            }

            boolean missingParent = false;
            for (final ResourceLocation parent: quest.getValue().getParents())
            {
                if (!finishedQuests.containsKey(parent))
                {
                    missingParent = true;
                    break;
                }
            }

            if (missingParent)
            {
                continue;
            }

            final IQuestInstance colonyQuest = quest.getValue().attemptStart(colony);
            if (colonyQuest != null)
            {
                this.availableQuests.put(quest.getKey(), colonyQuest);
                markDirty();
            }
        }

        for (final Map.Entry<ResourceLocation, IQuestInstance> availableQuest : new ArrayList<>(availableQuests.entrySet()))
        {
            if (!GLOBAL_SERVER_QUESTS.containsKey(availableQuest.getKey()) || !availableQuest.getValue().isValid(colony))
            {
                availableQuest.getValue().onDeletion();
                this.availableQuests.remove(availableQuest.getKey());
                markDirty();
            }
        }

        for (final Map.Entry<ResourceLocation, IQuestInstance> inProgressQuest : new ArrayList<>(inProgressQuests.entrySet()))
        {
            if (!GLOBAL_SERVER_QUESTS.containsKey(inProgressQuest.getKey()) || !inProgressQuest.getValue().isValid(colony))
            {
                inProgressQuest.getValue().onDeletion();
                this.inProgressQuests.remove(inProgressQuest.getKey());
                markDirty();
            }
        }
    }

    @Override
    public void deleteQuest(final ResourceLocation questID)
    {
        this.availableQuests.remove(questID);
        this.inProgressQuests.remove(questID);
        markDirty();
    }

    @Override
    public IQuestInstance getAvailableOrInProgressQuest(final ResourceLocation questId)
    {
        return availableQuests.containsKey(questId) ? availableQuests.get(questId) : inProgressQuests.get(questId);
    }

    @Override
    public void onWorldLoad()
    {
        for (final IQuestInstance colonyQuest : inProgressQuests.values())
        {
            colonyQuest.onWorldLoad();
        }
    }

    @Override
    public void unlockQuest(final ResourceLocation questId)
    {
        this.unlockedQuests.add(questId);
        markDirty();
    }

    @Override
    public boolean isUnlocked(final ResourceLocation questId)
    {
        return this.unlockedQuests.contains(questId);
    }

    @Override
    public CompoundTag serializeNBT()
    {
        final CompoundTag managerCompound = new CompoundTag();

        final ListTag availableListTag = new ListTag();
        for (final Map.Entry<ResourceLocation, IQuestInstance> available : availableQuests.entrySet())
        {
            availableListTag.add(available.getValue().serializeNBT());
        }
        managerCompound.put(TAG_AVAILABLE, availableListTag);

        final ListTag inProgressListTag = new ListTag();
        for (final Map.Entry<ResourceLocation, IQuestInstance> inProgress : inProgressQuests.entrySet())
        {
            inProgressListTag.add(inProgress.getValue().serializeNBT());
        }
        managerCompound.put(TAG_IN_PROGRESS, inProgressListTag);

        final ListTag finishedListTag = new ListTag();
        for (final Map.Entry<ResourceLocation, Integer> finished : finishedQuests.entrySet())
        {
            final CompoundTag finishedTag = new CompoundTag();
            finishedTag.putString(TAG_ID, finished.getKey().toString());
            finishedTag.putInt(TAG_QUANTITY, finished.getValue());
            finishedListTag.add(finishedTag);
        }
        managerCompound.put(TAG_FINISHED, finishedListTag);

        final ListTag unlockedListTag = new ListTag();
        for (final ResourceLocation unlocked : unlockedQuests)
        {
            final CompoundTag unlockedTag = new CompoundTag();
            unlockedTag.putString(TAG_ID, unlocked.toString());
            unlockedListTag.add(unlockedTag);
        }
        managerCompound.put(TAG_UNLOCKED, unlockedListTag);
        managerCompound.putDouble(TAG_REPUTATION, questReputation);

        return managerCompound;
    }

    @Override
    public void deserializeNBT(final CompoundTag nbt)
    {
        final Map<ResourceLocation, IQuestInstance> localAvailableQuests = new HashMap<>();
        final ListTag availableListTag = nbt.getList(TAG_AVAILABLE, Tag.TAG_COMPOUND);
        for (final Tag element : availableListTag)
        {
            final ResourceLocation key = new ResourceLocation(((CompoundTag) element).getString(TAG_ID));
            if (GLOBAL_SERVER_QUESTS.containsKey(key))
            {
                final IQuestInstance colonyQuest = availableQuests.containsKey(key) ? availableQuests.get(key) : new QuestInstance(colony);
                colonyQuest.deserializeNBT((CompoundTag) element);
                localAvailableQuests.put(colonyQuest.getId(), colonyQuest);
            }
        }

        this.availableQuests.clear();
        this.availableQuests.putAll(localAvailableQuests);

        final Map<ResourceLocation, IQuestInstance> localInProgressQuests = new HashMap<>();
        final ListTag inProgressListTag = nbt.getList(TAG_IN_PROGRESS, Tag.TAG_COMPOUND);
        for (final Tag element : inProgressListTag)
        {
            final ResourceLocation key = new ResourceLocation(((CompoundTag) element).getString(TAG_ID));
            if (GLOBAL_SERVER_QUESTS.containsKey(key))
            {
                final IQuestInstance colonyQuest = this.inProgressQuests.containsKey(key) ? this.inProgressQuests.get(key) : new QuestInstance(colony);
                colonyQuest.deserializeNBT((CompoundTag) element);
                localInProgressQuests.put(colonyQuest.getId(), colonyQuest);
            }
        }

        this.inProgressQuests.clear();
        this.inProgressQuests.putAll(localInProgressQuests);


        this.finishedQuests.clear();
        final ListTag finishedListTag = nbt.getList(TAG_FINISHED, Tag.TAG_COMPOUND);
        for (final Tag element : finishedListTag)
        {
            this.finishedQuests.put(new ResourceLocation(((CompoundTag) element).getString(TAG_ID)), ((CompoundTag) element).getInt(TAG_QUANTITY));
        }
        finishedQuestsCache = null;

        this.unlockedQuests.clear();
        final ListTag unlockedListTag = nbt.getList(TAG_UNLOCKED, Tag.TAG_COMPOUND);
        for (final Tag element : unlockedListTag)
        {
            this.unlockedQuests.add(new ResourceLocation(((CompoundTag) element).getString(TAG_ID)));
        }
        this.questReputation = nbt.getDouble(TAG_REPUTATION);
    }

    @Override
    public void serialize(final FriendlyByteBuf buf, final boolean hasNewSubscribers)
    {
        buf.writeBoolean(isDirty || hasNewSubscribers);
        if (isDirty || hasNewSubscribers)
        {
            buf.writeNbt(serializeNBT());
        }
        isDirty = false;
    }

    @Override
    public void deserialize(final FriendlyByteBuf buf)
    {
        final boolean hasData = buf.readBoolean();
        if (hasData)
        {
            deserializeNBT(buf.readNbt());
        }
    }

    @Override
    public void markDirty()
    {
        isDirty = true;
    }

    @Override
    public List<IQuestInstance> getAvailableQuests()
    {
        return new ArrayList<>(availableQuests.values());
    }

    @Override
    public List<IQuestInstance> getInProgressQuests()
    {
        return new ArrayList<>(inProgressQuests.values());
    }

    @Override
    public List<FinishedQuest> getFinishedQuests()
    {
        if (finishedQuestsCache == null)
        {
            List<FinishedQuest> data = new ArrayList<>();
            for (Map.Entry<ResourceLocation, Integer> entry : finishedQuests.entrySet())
            {
                IQuestTemplate template = GLOBAL_SERVER_QUESTS.get(entry.getKey());
                if (template != null)
                {
                    data.add(new FinishedQuest(template, entry.getValue()));
                }
            }
            finishedQuestsCache = Collections.unmodifiableList(data);
        }
        return finishedQuestsCache;
    }

    @Override
    public void injectAvailableQuest(final IQuestInstance questInstance)
    {
        this.availableQuests.put(questInstance.getId(), questInstance);
        markDirty();
    }
}

package com.minecolonies.core.quests;

import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.quests.*;
import com.minecolonies.api.quests.IQuestTemplate;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Player;

import java.util.List;
import java.util.function.Function;

/**
 * Instance of a specific quest type
 */
public class QuestTemplate implements IQuestTemplate
{
    /**
     * The unique id of this quest.
     */
    private final ResourceLocation questID;

    /**
     * List of parents to fulfill before this can start.
     */
    private final List<ResourceLocation> parents;

    /**
     * List of quest triggers assigned to this quest data including the trigger order.
     */
    private final Function<IColony, List<ITriggerReturnData<?>>> questTriggerList;

    private final List<IQuestObjectiveTemplate> objectives;

    private final List<IQuestRewardTemplate> questRewards;


    private final int maxOccurrence;

    private final Component name;

    /**
     * How long the quest stays active/available.
     */
    private final int questTimeout;

    /**
     * Create new quest data.
     * @param questID the id of the quest.
     * @param name the name of the quest.
     * @param parents the parent quests.
     * @param maxOccurrence the max num of occurrences.
     * @param questTriggerList the list of triggers.
     * @param questObjectives the quest objectives.
     * @param questTimeout the time until it times out.
     * @param questRewards its rewards
     */
    public QuestTemplate(final ResourceLocation questID, final Component name,
      final List<ResourceLocation> parents,
      final int maxOccurrence, final Function<IColony, List<ITriggerReturnData<?>>> questTriggerList, final List<IQuestObjectiveTemplate> questObjectives, final int questTimeout, final List<IQuestRewardTemplate> questRewards)
    {
        this.questID = questID;
        this.name = name;
        this.parents = parents;
        this.questTriggerList = questTriggerList;
        this.maxOccurrence = maxOccurrence;
        this.objectives = questObjectives;
        this.questTimeout = questTimeout;
        this.questRewards = questRewards;
    }

    @Override
    public IQuestInstance attemptStart(final IColony colony)
    {
        final List<ITriggerReturnData<?>> triggerReturnData = questTriggerList.apply(colony);
        return (triggerReturnData == null || triggerReturnData.isEmpty()) ? null : new QuestInstance(questID, colony, triggerReturnData);
    }

    @Override
    public int getQuestTimeout()
    {
        return questTimeout;
    }

    @Override
    public int getMaxOccurrence()
    {
        return maxOccurrence;
    }

    @Override
    public void unlockQuestRewards(final IColony colony, final Player player, final IQuestInstance colonyQuest, final List<Integer> unlockedRewards)
    {
        int index = 0;
        for (final IQuestRewardTemplate questReward : questRewards)
        {
            if (unlockedRewards.contains(index))
            {
                questReward.applyReward(colony, player, colonyQuest);
            }
            index+=1;
        }
    }

    @Override
    public IQuestObjectiveTemplate getObjective(final int index)
    {
        return objectives.get(index);
    }

    @Override
    public int getObjectiveCount()
    {
        return objectives.size();
    }

    @Override
    public Component getName()
    {
        return this.name;
    }

    @Override
    public List<ResourceLocation> getParents()
    {
        return this.parents;
    }
}

