import java.util.ArrayList;
import java.util.List;

/**
 * The implementation of the IGlobalResearch interface which represents the research on the global level.
 */
public class GlobalResearch implements IGlobalResearch
{
    /**
     * The costList of the research.
     */
    private final List<IResearchCost> costList = new ArrayList<>();

    /**
     * The id of the research.
     */
    private final ResourceLocation id;

    /**
     * The id of the parent research which has to be completed first.
     */
    @Nullable
    private final ResourceLocation parent;

    /**
     * The research branch id.
     */
    private final ResourceLocation branch;

    /**
     * The pre-localized name for the research.
     */
    private final TranslatableContents name;

    /**
     * Subtitle names for the research.  Optional, and only shows up rarely.
     */
    private final TranslatableContents subtitle;

    /**
     * The research effects of this research.
     */
    private final List<IResearchEffect> effects = new ArrayList<>();

    /**
     * The depth level in the tree.
     */
    private final int depth;

    /**
     * The sort order of the research.
     */
    private final int sortOrder;

    /**
     * If the research has an only child.
     */
    private final boolean onlyChild;

    /**
     * If the research has an only child.
     */
    private final boolean hidden;

    /**
     * If the research starts automatically when requirements met.
     */
    private final boolean autostart;

    /**
     * If the research has an only child.
     */
    private final boolean instant;

    /**
     * If the research can be reset or unlearned after being unlocked.
     */
    private final boolean immutable;

    /**
     * List of children of research.
     */
    private final List<ResourceLocation> children = new ArrayList<>();

    /**
     * The requirement for this research.
     */
    private final List<IResearchRequirement> requirements = new ArrayList<>();

    /**
     * Create the new research with multiple effects
     *
     * @param id        its id.
     * @param parent    the research's parent, if one is present, or null if not.
     * @param branch    the branch it is on.
     * @param name      the optional name of the research. If empty, a key generated from the id will be used instead.
     * @param subtitle  the optional short description of the research, in plaintext or as a translation key.
     * @param depth     the depth in the tree.
     * @param sortOrder the relative vertical order of the research's display, in relation to its siblings.
     * @param onlyChild if the research allows only one child research to be completed.
     * @param hidden    if the research is only visible when eligible to be researched.
     * @param autostart if the research should begin automatically, or notify the player, when it is eligible.
     * @param instant   if the research should be completed instantly (ish) from when begun.
     * @param immutable if the research can not be reset once unlocked.
     */
    public GlobalResearch(
        final ResourceLocation id,
        final @Nullable ResourceLocation parent,
        final ResourceLocation branch,
        final TranslatableContents name,
        final TranslatableContents subtitle,
        final int depth,
        final int sortOrder,
        final boolean onlyChild,
        final boolean hidden,
        final boolean autostart,
        final boolean instant,
        final boolean immutable)
    {
        this.id = id;
        this.name = name;
        this.subtitle = subtitle;
        this.branch = branch;
        this.parent = parent;
        this.depth = depth;
        this.sortOrder = sortOrder;
        this.onlyChild = onlyChild;
        this.hidden = hidden;
        this.autostart = autostart;
        this.instant = instant;
        this.immutable = immutable;
    }

    @Override
    public boolean canResearch(@NotNull IBuilding building, @NotNull final ILocalResearchTree localTree)
    {
        final int uni_level = building.getBuildingLevel() == building.getMaxBuildingLevel() ? Integer.MAX_VALUE : building.getBuildingLevel();
        final IGlobalResearch parentResearch = parent == null ? null : IGlobalResearchTree.getInstance().getResearch(branch, parent);
        final ILocalResearch localParentResearch = parent == null ? null : localTree.getResearch(branch, parent);
        final ILocalResearch localResearch = localTree.getResearch(this.getBranch(), this.getId());

        return (localResearch == null) && canDisplay(uni_level) && (parentResearch == null
            || localParentResearch != null && localParentResearch.getState() == ResearchState.FINISHED) && (parentResearch == null || !parentResearch.hasResearchedChild(localTree)
            || !parentResearch.hasOnlyChild()) && (depth < 6 || !localTree.branchFinishedHighestLevel(branch));
    }

    @Override
    public boolean canDisplay(final int uni_level)
    {
        return uni_level >= depth;
    }

    /**
     * Checks if there are enough resources between the player inventory 
     * and the university's inventory to start this research.
     *
     * @param player the player to check.
     * @param universityPos the position of the university to check.
     * @return true if the player has enough resources.
     */
    @Override
    public boolean hasEnoughResources(final @NotNull Player player, final @NotNull BlockPos universityPos)
    {
        if (costList.isEmpty())
        {
            return true;
        }

        final IItemHandler playerInventory = new InvWrapper(player.getInventory());

        ICommonBuilding buildingInv = BuildingUtils.commonBuildingFromPosition(player.level(), universityPos);

        for (final IResearchCost ingredient : costList)
        {
            int totalCount = 0;
            for (final Item cost : ingredient.getItems())
            {

                if (buildingInv != null)
                {
                    final int count = InventoryUtils.hasBuildingEnoughElseCount(buildingInv, stack -> IGlobalResearch.isUniversityResearchMatch(stack, cost), ingredient.getCount());
                    totalCount += count;
                }

                if (totalCount < ingredient.getCount())
                {
                    final int count = InventoryUtils.getItemCountInItemHandler(playerInventory, stack -> IGlobalResearch.isPlayerResearchMatch(stack, cost));
                    totalCount += count;
                }
            }
            if (totalCount < ingredient.getCount())
            {
                return false;
            }
        }
        return true;
    }

    @Override
    public List<IResearchCost> getCostList()
    {
        return ImmutableList.copyOf(costList);
    }

    @Override
    public void startResearch(@NotNull final ILocalResearchTree localResearchTree)
    {
        if (localResearchTree.getResearch(this.branch, this.id) == null)
        {
            final ILocalResearch research = new LocalResearch(this.id, this.branch, this.depth);
            if (this.instant)
            {
                research.setProgress(IGlobalResearchTree.getInstance().getBranchData(branch).getBaseTime(research.getDepth()));
            }
            research.setState(ResearchState.IN_PROGRESS);
            localResearchTree.addResearch(branch, research);
        }
    }

    @NotNull
    @Override
    public ResourceLocation getId()
    {
        return this.id;
    }

    @Override
    public TranslatableContents getName() { return this.name; }

    @Override
    public TranslatableContents getSubtitle()
    {
        return this.subtitle;
    }

    @Override
    @Nullable
    public ResourceLocation getParent()
    {
        return this.parent;
    }

    @Override
    public ResourceLocation getBranch()
    {
        return this.branch;
    }

    @Override
    public int getDepth()
    {
        return this.depth;
    }

    @Override
    public int getSortOrder()
    {
        return this.sortOrder;
    }

    @Override
    public boolean isInstant()
    {
        return this.instant;
    }

    @Override
    public boolean isHidden()
    {
        return this.hidden;
    }

    @Override
    public boolean isAutostart()
    {
        return this.autostart;
    }

    @Override
    public boolean isImmutable()
    {
        return this.immutable;
    }

    @Override
    public boolean hasOnlyChild()
    {
        return onlyChild;
    }

    @Override
    public boolean hasResearchedChild(@NotNull final ILocalResearchTree localTree)
    {
        for (final ResourceLocation child : this.children)
        {
            final IGlobalResearch childResearch = IGlobalResearchTree.getInstance().getResearch(branch, child);
            final ILocalResearch localResearch = localTree.getResearch(childResearch.getBranch(), childResearch.getId());
            if (localResearch != null)
            {
                return true;
            }
        }
        return false;
    }

    @Override
    public void addChild(final IGlobalResearch child)
    {
        this.children.add(child.getId());
    }

    @Override
    public void addChild(final ResourceLocation child)
    {
        this.children.add(child);
    }

    @Override
    public void addCost(final IResearchCost cost)
    {
        costList.add(cost);
    }

    public void addEffect(final IResearchEffect effect)
    {
        effects.add(effect);
    }

    public void addRequirement(final IResearchRequirement requirement)
    {
        this.requirements.add(requirement);
    }

    @Override
    public List<IResearchRequirement> getResearchRequirements()
    {
        return this.requirements;
    }

    @Override
    public List<ResourceLocation> getChildren()
    {
        return this.children;
    }

    @Override
    public List<IResearchEffect> getEffects()
    {
        return this.effects;
    }
}

package com.minecolonies.core.research;

import com.minecolonies.api.research.IGlobalResearchTree;
import com.minecolonies.api.research.ILocalResearch;
import com.minecolonies.api.research.ILocalResearchTree;
import com.minecolonies.api.research.IResearchEffect;
import com.minecolonies.api.research.IResearchEffectManager;
import com.minecolonies.api.research.util.ResearchState;
import net.minecraft.resources.ResourceLocation;

/**
 * The implementation of the ILocalResearch interface which represents one type of research, stored in each colony.
 */
public class LocalResearch implements ILocalResearch
{
    /**
     * Depth of research.
     */
    private final int depth;

    /**
     * The current research state.
     */
    private ResearchState state;

    /**
     * The id of the research.
     */
    private final ResourceLocation id;

    /**
     * The research branch.
     */
    private final ResourceLocation branch;

    /**
     * The progress of the research.
     */
    private int progress;

    /**
     * Create the new research.
     *
     * @param id     it's id.
     * @param depth  the depth in the tree.
     * @param branch the branch it is on.
     */
    public LocalResearch(final ResourceLocation id, final ResourceLocation branch, final int depth)
    {
        this.id = id;
        this.depth = depth;
        this.branch = branch;
    }

    @Override
    public boolean research(final IResearchEffectManager effects, final ILocalResearchTree tree)
    {
        if (state == ResearchState.IN_PROGRESS)
        {
            progress++;
            if (progress >= IGlobalResearchTree.getInstance().getBranchData(branch).getBaseTime(this.depth))
            {
                state = ResearchState.FINISHED;
                for(final IResearchEffect effect : IGlobalResearchTree.getInstance().getResearch(this.branch, this.getId()).getEffects())
                {
                    effects.applyEffect(effect);
                }
                tree.finishResearch(this.id);
                return true;
            }
        }
        return false;
    }

    @Override
    public int getProgress()
    {
        return progress;
    }

    @Override
    public ResourceLocation getId()
    {
        return this.id;
    }

    @Override
    public ResearchState getState()
    {
        return this.state;
    }

    @Override
    public ResourceLocation getBranch()
    {
        return this.branch;
    }

    @Override
    public int getDepth()
    {
        return depth;
    }

    @Override
    public void setState(final ResearchState value)
    {
        this.state = value;
    }

    @Override
    public void setProgress(final int progress)
    {
        this.progress = progress;
    }
}

package com.minecolonies.core.research;

import com.google.common.reflect.TypeToken;
import com.minecolonies.api.colony.requestsystem.factory.FactoryVoidInput;
import com.minecolonies.api.colony.requestsystem.factory.IFactoryController;
import com.minecolonies.api.research.ILocalResearch;
import com.minecolonies.api.research.factories.ILocalResearchFactory;
import com.minecolonies.api.research.util.ResearchState;
import com.minecolonies.api.util.constant.SerializationIdentifierConstants;
import com.minecolonies.api.util.constant.TypeConstants;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.resources.ResourceLocation;
import org.jetbrains.annotations.NotNull;

import static com.minecolonies.api.research.util.ResearchConstants.*;

/**
 * Factory implementation taking care of creating new instances, serializing and deserializing LocalResearch.
 */
public class LocalResearchFactory implements ILocalResearchFactory
{
    @NotNull
    @Override
    public TypeToken<LocalResearch> getFactoryOutputType()
    {
        return TypeToken.of(LocalResearch.class);
    }

    @NotNull
    @Override
    public TypeToken<FactoryVoidInput> getFactoryInputType()
    {
        return TypeConstants.FACTORYVOIDINPUT;
    }

    @NotNull
    @Override
    public ILocalResearch getNewInstance(final ResourceLocation id, final ResourceLocation branch, final int depth)
    {
        return new LocalResearch(id, branch, depth);
    }

    @NotNull
    @Override
    public CompoundTag serialize(@NotNull final IFactoryController controller, @NotNull final ILocalResearch research)
    {
        final CompoundTag compound = new CompoundTag();
        compound.putInt(TAG_STATE, research.getState().ordinal());
        compound.putString(TAG_ID, research.getId().toString());
        compound.putString(TAG_BRANCH, research.getBranch().toString());
        compound.putInt(TAG_PROGRESS, research.getProgress());
        compound.putInt(TAG_RESEARCH_LVL, research.getDepth());

        return compound;
    }

    @NotNull
    @Override
    public ILocalResearch deserialize(@NotNull final IFactoryController controller, @NotNull final CompoundTag nbt)
    {
        final int state = nbt.getInt(TAG_STATE);
        final ResourceLocation id = new ResourceLocation(nbt.getString(TAG_ID));
        final ResourceLocation branch = new ResourceLocation(nbt.getString(TAG_BRANCH));
        final int depth = nbt.getInt(TAG_RESEARCH_LVL);
        final int progress = nbt.getInt(TAG_PROGRESS);

        final ILocalResearch research = getNewInstance(id, branch, depth);
        research.setState(ResearchState.values()[state]);
        research.setProgress(progress);
        return research;
    }

    @Override
    public void serialize(IFactoryController controller, ILocalResearch input, FriendlyByteBuf packetBuffer)
    {
        packetBuffer.writeInt(input.getState().ordinal());
        packetBuffer.writeUtf(input.getId().toString());
        packetBuffer.writeResourceLocation(input.getBranch());
        packetBuffer.writeInt(input.getProgress());
        packetBuffer.writeInt(input.getDepth());
    }

    @Override
    public ILocalResearch deserialize(IFactoryController controller, FriendlyByteBuf buffer) throws Throwable
    {
        final int state = buffer.readInt();
        final ResourceLocation id = buffer.readResourceLocation();
        final ResourceLocation branch = buffer.readResourceLocation();
        final int progress = buffer.readInt();
        final int depth = buffer.readInt();

        final ILocalResearch research = getNewInstance(id, branch, depth);
        research.setState(ResearchState.values()[state]);
        research.setProgress(progress);
        return research;
    }

    @Override
    public short getSerializationId()
    {
        return SerializationIdentifierConstants.LOCAL_RESEARCH_ID;
    }
}

package com.minecolonies.core.research;

import com.google.common.collect.ImmutableList;
import com.minecolonies.api.MinecoloniesAPIProxy;
import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.colony.requestsystem.StandardFactoryController;
import com.minecolonies.api.crafting.ItemStorage;
import com.minecolonies.api.research.*;
import com.minecolonies.api.research.util.ResearchState;
import com.minecolonies.api.util.*;
import com.minecolonies.core.colony.buildings.workerbuildings.BuildingUniversity;
import com.minecolonies.core.event.QuestObjectiveEventHandler;

import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.Tag;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraftforge.items.wrapper.InvWrapper;

import java.util.*;
import static com.minecolonies.api.research.util.ResearchConstants.MAX_DEPTH;
import static com.minecolonies.api.research.util.ResearchConstants.TAG_RESEARCH_TREE;
import static com.minecolonies.api.util.constant.TranslationConstants.MESSAGE_RESEARCH_STARTED;

/**
 * The class which contains all research.
 */
public class LocalResearchTree implements ILocalResearchTree
{
    /**
     * The map containing all researches by ID.
     */
    private final Map<ResourceLocation, Map<ResourceLocation, ILocalResearch>> researchTree = new HashMap<>();

    /**
     * All research in progress.
     */
    private final Map<ResourceLocation, ILocalResearch> inProgress = new HashMap<>();

    /**
     * All completed research.
     */
    private final Set<ResourceLocation> isComplete = new HashSet<>();

    /**
     * Map containing all branches for which the max level research has been occupied already.
     */
    private final Set<ResourceLocation> maxLevelResearchCompleted = new HashSet<>();

    /**
     * The colony reference.
     */
    public final IColony colony;

    public LocalResearchTree(final IColony colony)
    {
        this.colony = colony;
    }

    @Override
    public ILocalResearch getResearch(final ResourceLocation branch, final ResourceLocation id)
    {
        if (!researchTree.containsKey(branch))
        {
            return null;
        }
        return researchTree.get(branch).get(id);
    }

    @Override
    public boolean hasCompletedResearch(final ResourceLocation researchId)
    {
        if (IGlobalResearchTree.getInstance().hasResearch(researchId))
        {
            return isComplete.contains(researchId);
        }
        // For now, if a research requirement doesn't exist, we'll act as though it was completed.
        else
        {
            return true;
        }
    }

    @Override
    public void addResearch(final ResourceLocation branch, final ILocalResearch research)
    {
        if (!researchTree.containsKey(branch))
        {
            researchTree.put(branch, new HashMap<>());
        }

        if (!researchTree.get(branch).containsKey(research.getId()))
        {
            researchTree.get(branch).put(research.getId(), research);
        }

        if (research.getState() == ResearchState.IN_PROGRESS)
        {
            inProgress.put(research.getId(), research);
        }
        else if (research.getState() == ResearchState.FINISHED)
        {
            inProgress.remove(research.getId());
            isComplete.add(research.getId());

            QuestObjectiveEventHandler.onResearchComplete(colony, research.getId());
        }

        if (research.getDepth() == MAX_DEPTH)
        {
            maxLevelResearchCompleted.add(branch);
        }
    }

    @Override
    public boolean branchFinishedHighestLevel(final ResourceLocation branch)
    {
        return maxLevelResearchCompleted.contains(branch);
    }

    @Override
    public List<ILocalResearch> getResearchInProgress()
    {
        return ImmutableList.copyOf(inProgress.values());
    }

    @Override
    public void finishResearch(final ResourceLocation id)
    {
        inProgress.remove(id);
        isComplete.add(id);

        QuestObjectiveEventHandler.onResearchComplete(colony, id);
    }

    /**
     * Attempt to begin a research.
     * @param player     the player(s) making the request (and to apply costs toward)
     * @param colony     the colony doing the research
     * @param building   the university building that the player is standing in (or null if not in a university)
     * @param research   the research.
     */
    @Override
    public void attemptBeginResearch(final Player player, final IColony colony, final BuildingUniversity building, final IGlobalResearch research)
    {
        if (colony.getResearchManager().getResearchTree().getResearch(research.getBranch(), research.getId()) == null)
        {
            if (player.isCreative())
            {
                research.startResearch(colony.getResearchManager().getResearchTree());
                if (MinecoloniesAPIProxy.getInstance().getConfig().getServer().researchCreativeCompletion.get())
                {
                    colony.getResearchManager()
                      .getResearchTree()
                      .getResearch(research.getBranch(), research.getId())
                      .setProgress(IGlobalResearchTree.getInstance().getBranchData(research.getBranch()).getBaseTime(research.getDepth()));
                }
                colony.getResearchManager().markDirty();
                SoundUtils.playSuccessSound(player, player.blockPosition());
                colony.getResearchManager().markDirty();
                return;
            }

            if (!research.hasEnoughResources(player, building.getPosition()))
            {
                MessageUtils.format("com.minecolonies.coremod.research.costnotavailable", MutableComponent.create(research.getName())).sendTo(player);
                SoundUtils.playErrorSound(player, player.blockPosition());
                return;
            }
            if (!research.getResearchRequirements().isEmpty())
            {
                for (IResearchRequirement requirement : research.getResearchRequirements())
                {
                    if (!requirement.isFulfilled(colony))
                    {
                        MessageUtils.format("com.minecolonies.coremod.research.requirementnotmet").sendTo(player);
                        SoundUtils.playErrorSound(player, player.blockPosition());
                        return;
                    }
                }
            }

            // We know the university or player has the items, so now we can remove them safely.
            for (IResearchCost cost : research.getCostList())
            {
                for (Item item : cost.getItems())
                {
                    ItemStorage itemsToTake = new ItemStorage(item, cost.getCount());
                    InventoryUtils.reduceBuildingThenPlayerInventory(building,  player, itemsToTake, stack -> IGlobalResearch.isUniversityResearchMatch(stack, item), stack -> IGlobalResearch.isPlayerResearchMatch(stack, item));
                }

            }

            MessageUtils.format(MESSAGE_RESEARCH_STARTED, MutableComponent.create(research.getName())).sendTo(player);
            research.startResearch(colony.getResearchManager().getResearchTree());
            colony.getResearchManager().markDirty();
            SoundUtils.playSuccessSound(player, player.blockPosition());
        }
        else
        {
            if (player.isCreative())
            {
                if (MinecoloniesAPIProxy.getInstance().getConfig().getServer().researchCreativeCompletion.get())
                {
                    colony.getResearchManager()
                      .getResearchTree()
                      .getResearch(research.getBranch(), research.getId())
                      .setProgress(IGlobalResearchTree.getInstance().getBranchData(research.getBranch()).getBaseTime(research.getDepth()));
                    colony.getResearchManager().markDirty();
                }
            }
            else
            {
                MessageUtils.format("com.minecolonies.coremod.research.alreadystarted").sendTo(player);
                SoundUtils.playErrorSound(player, player.blockPosition());
            }
        }
        colony.markDirty();
    }

    @Override
    public void attemptResetResearch(final Player player, final IColony colony, final ILocalResearch research)
    {
        // If in progress and get another request, cancel research, and remove it from the local tree.
        if (research.getState() == ResearchState.IN_PROGRESS)
        {
            MessageUtils.format("com.minecolonies.coremod.research.stopped",
                MutableComponent.create(IGlobalResearchTree.getInstance().getResearch(research.getBranch(), research.getId()).getName()))
              .sendTo(player);
            SoundUtils.playSuccessSound(player, player.blockPosition());
            removeResearch(research.getBranch(), research.getId());
            colony.getResearchManager().markDirty();
        }
        // If complete, it's a request to undo the research.
        else if (research.getState() == ResearchState.FINISHED)
        {
            for (ResourceLocation childIds : IGlobalResearchTree.getInstance().getResearch(research.getBranch(), research.getId()).getChildren())
            {
                if (researchTree.get(research.getBranch()).get(childIds) != null)
                {
                    MessageUtils.format("com.minecolonies.coremod.research.undo.haschilds").sendTo(player);
                    SoundUtils.playErrorSound(player, player.blockPosition());
                    return;
                }
            }

            if (!player.isCreative())
            {
                final List<ItemStorage> costList = IGlobalResearchTree.getInstance().getResearchResetCosts();
                final InvWrapper playerInv = new InvWrapper(player.getInventory());
                for (final ItemStorage cost : costList)
                {
                    final int count = InventoryUtils.getItemCountInItemHandler(playerInv,
                      stack -> ItemStackUtils.compareItemStacksIgnoreStackSize(stack, cost.getItemStack(), !cost.ignoreDamageValue(), !cost.ignoreNBT()));
                    if (count < cost.getAmount())
                    {
                        MessageUtils.format("com.minecolonies.coremod.research.costnotavailable",
                          MutableComponent.create(IGlobalResearchTree.getInstance().getResearch(research.getBranch(), research.getId()).getName())).sendTo(player);
                        SoundUtils.playErrorSound(player, player.blockPosition());
                        return;
                    }
                }
                for (ItemStorage cost : costList)
                {
                    final List<Integer> slotsWithMaterial = InventoryUtils.findAllSlotsInItemHandlerWith(playerInv,
                      stack -> ItemStackUtils.compareItemStacksIgnoreStackSize(stack, cost.getItemStack(), !cost.ignoreDamageValue(), !cost.ignoreNBT()));
                    int amount = cost.getAmount();
                    for (Integer slotNum : slotsWithMaterial)
                    {
                        amount = amount - playerInv.extractItem(slotNum, amount, false).getCount();
                        if (amount <= 0)
                        {
                            break;
                        }
                    }
                }
            }
            MessageUtils.format("com.minecolonies.coremod.research.undo",
                MutableComponent.create(IGlobalResearchTree.getInstance().getResearch(research.getBranch(), research.getId()).getName()))
              .sendTo(player);
            SoundUtils.playSuccessSound(player, player.blockPosition());
            removeResearch(research.getBranch(), research.getId());
            resetEffects(colony);
            colony.getResearchManager().markDirty();
        }
        colony.markDirty();
    }

    /**
     * Does the heavy lifting to remove research and, optionally, effects.
     *
     * @param branch The research branch id.
     * @param id     The research id.
     */
    private void removeResearch(final ResourceLocation branch, final ResourceLocation id)
    {
        if (!researchTree.get(branch).containsKey(id))
        {
            Log.getLogger().warn("Something went wrong: player attempted to reset research that does not exist or is not started");
        }
        researchTree.get(branch).remove(id);
        inProgress.remove(id);
        isComplete.remove(id);
        if (IGlobalResearchTree.getInstance().getResearch(branch, id).getDepth() == MAX_DEPTH)
        {
            maxLevelResearchCompleted.remove(branch);
        }
    }

    /**
     * Resets effects for a specific colony.
     *
     * @param colony The colony to reset research effects.
     */
    private void resetEffects(IColony colony)
    {
        if (colony != null)
        {
            // There's no guarantee that undoing a research will only push its effects back one strength grade.
            // Instead, we have to apply every extant effect again.
            // Because effects may cross branches, must check all branches, not just the current one.
            colony.getResearchManager().getResearchEffects().removeAllEffects();
            for (final Map.Entry<ResourceLocation, Map<ResourceLocation, ILocalResearch>> branch : researchTree.entrySet())
            {
                for (final Map.Entry<ResourceLocation, ILocalResearch> research : branch.getValue().entrySet())
                {
                    if (research.getValue().getState() == ResearchState.FINISHED)
                    {
                        for (final IResearchEffect effect : IGlobalResearchTree.getInstance().getResearch(branch.getKey(), research.getValue().getId()).getEffects())
                        {
                            colony.getResearchManager().getResearchEffects().applyEffect(effect);
                            colony.getResearchManager().markDirty();
                        }
                    }
                }
            }
        }
    }

    @Override
    public void writeToNBT(final CompoundTag compound)
    {
        final ListTag researchList = new ListTag();
        for (final Map<ResourceLocation, ILocalResearch> researchMap : researchTree.values())
        {
            for (final ILocalResearch research : researchMap.values())
            {
                researchList.add(StandardFactoryController.getInstance().serialize(research));
            }
        }

        compound.put(TAG_RESEARCH_TREE, researchList);
    }

    @Override
    public void readFromNBT(final CompoundTag compound, final IResearchEffectManager effects)
    {
        researchTree.clear();
        inProgress.clear();
        isComplete.clear();
        maxLevelResearchCompleted.clear();
        NBTUtils.streamCompound(compound.getList(TAG_RESEARCH_TREE, Tag.TAG_COMPOUND))
          .map(researchCompound -> (ILocalResearch) StandardFactoryController.getInstance().deserialize(researchCompound))
          .forEach(research -> {
              /// region Updated ID helper.
              if (!MinecoloniesAPIProxy.getInstance().getGlobalResearchTree().hasResearch(research.getBranch(), research.getId()))
              {
                  if (research.getBranch().getNamespace().contains("minecraft"))
                  {
                      final ResearchState currentState = research.getState();
                      final int progress = research.getProgress();
                      research = new LocalResearch(new ResourceLocation(com.minecolonies.api.util.constant.Constants.MOD_ID, research.getId().getPath()),
                        new ResourceLocation(com.minecolonies.api.util.constant.Constants.MOD_ID, research.getBranch().getPath()), research.getDepth());
                      research.setState(currentState);
                      research.setProgress(progress);
                  }
                  else
                  {
                      if (MinecoloniesAPIProxy.getInstance().getConfig().getServer().researchDebugLog.get())
                      {
                          Log.getLogger().warn("Research " + research.getId() + " was in colony save file, but was not in CompatMap.");
                      }
                  }
              }
              /// endregion

              if (research.getState() == ResearchState.FINISHED)
              {
                  // Even after correction, we do still need to check for presence; it's possible for someone to have old save data and remove the research,
                  // or to have a different research that was in a now-removed data pack.  But those will get just thrown away.
                  if (MinecoloniesAPIProxy.getInstance().getGlobalResearchTree().hasResearch(research.getBranch(), research.getId()))
                  {
                      for (final IResearchEffect effect : MinecoloniesAPIProxy.getInstance()
                        .getGlobalResearchTree()
                        .getResearch(research.getBranch(), research.getId())
                        .getEffects())
                      {
                          effects.applyEffect(effect);
                      }
                  }
                  else
                  {
                      if (MinecoloniesAPIProxy.getInstance().getConfig().getServer().researchDebugLog.get())
                      {
                          Log.getLogger()
                            .warn("Research " + research.getId() + " was in colony save file, but not found as valid current research.  Progress on this research may be reset.");
                      }
                  }
              }
              addResearch(research.getBranch(), research);
          });
    }

    @Override
    public List<ResourceLocation> getCompletedList()
    {
        return new ArrayList<>(isComplete);
    }

    @Override
    public boolean isComplete(final ResourceLocation location)
    {
        return isComplete.contains(location);
    }
}

package com.minecolonies.core.research;

import com.minecolonies.api.research.IResearchEffect;
import com.minecolonies.api.research.IResearchEffectManager;
import net.minecraft.resources.ResourceLocation;

import java.util.HashMap;
import java.util.Map;

/**
 * The map of unlocked research effects of a given colony.
 */
public class ResearchEffectManager implements IResearchEffectManager
{
    /**
     * The map of the research effects, from a string identifier to the effect.
     */
    private final Map<ResourceLocation, IResearchEffect> effectMap = new HashMap<>();

    @Override
    public double getEffectStrength(final ResourceLocation id)
    {
        final IResearchEffect effect = effectMap.get(id);
        if (effect instanceof GlobalResearchEffect globalResearchEffect)
        {
            return globalResearchEffect.getEffect();
        }
        return 0;
    }

    @Override
    public void applyEffect(final IResearchEffect effect)
    {
        final IResearchEffect effectInMap = effectMap.get(effect.getId());
        if (effectInMap != null)
        {
            if (effect.overrides(effectInMap))
            {
                effectMap.put(effect.getId(), effect);
            }
        }
        else
        {
            effectMap.put(effect.getId(), effect);
        }
    }

    @Override
    public void removeAllEffects()
    {
        effectMap.clear();
    }
}
